$path = 'src\WayFinder.EntityFrameworkCore\EntityFrameworkCore\WayFinderDbContext.cs'
$text = [IO.File]::ReadAllText($path, [Text.Encoding]::GetEncoding('iso-8859-1'))
$target = "builder.Entity<DestinoFavorito>(b =>`r`n        {`r`n            b.ToTable(WayFinderConsts.DbTablePrefix + `"DestinosFavoritos`", WayFinderConsts.DbSchema);`r`n            b.ConfigureByConvention();`r`n`r`n            // Regla de Oro: Un usuario NO puede guardar el mismo destino 2 veces.`r`n            b.HasIndex(x => new { x.CreatorId, x.DestinoTuristicoId }).IsUnique();`r`n        });"
$newConfig = $target + "`r`n`r`n        builder.Entity<WayFinder.Experiencias.ExperienciaViaje>(b =>`r`n        {`r`n            b.ToTable(WayFinderConsts.DbTablePrefix + `"ExperienciasViajes`", WayFinderConsts.DbSchema);`r`n            b.ConfigureByConvention();`r`n            b.Property(x => x.Titulo).IsRequired().HasMaxLength(128);`r`n            b.Property(x => x.Descripcion).IsRequired().HasMaxLength(2048);`r`n            b.Property(x => x.Valoracion).IsRequired().HasMaxLength(32);`r`n            b.HasOne<DestinoTuristico>().WithMany().HasForeignKey(x => x.DestinoId).IsRequired().OnDelete(Microsoft.EntityFrameworkCore.DeleteBehavior.Cascade);`r`n            b.HasOne<Volo.Abp.Identity.IdentityUser>().WithMany().HasForeignKey(x => x.UsuarioId).IsRequired().OnDelete(Microsoft.EntityFrameworkCore.DeleteBehavior.NoAction);`r`n        });"
$text = $text.Replace($target, $newConfig)
$text = $text.Replace("public DbSet<ExperienciaViaje> ExperienciasViajes { get; set; }", "public DbSet<WayFinder.Experiencias.ExperienciaViaje> ExperienciasViajes { get; set; }")
[IO.File]::WriteAllText($path, $text, [Text.Encoding]::UTF8)
